import * as THREE from 'three';
import {GLTFLoader} from './vendor/loaders/GLTFLoader.js';
import {OrbitControls} from './vendor/controls/OrbitControls.js';
import {jointAngle} from './geometry.js';

export async function initBodyViewer(container,state){
 const scene=new THREE.Scene();scene.background=new THREE.Color('#fafaf7');scene.fog=new THREE.Fog('#fafaf7',25,85);
 const camera=new THREE.PerspectiveCamera(35,1,.02,180);camera.position.set(3,1.6,4.2);
 let renderer;try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'low-power'});}catch{container.querySelector('#viewer-status').textContent='EL DISPOSITIVO NO PUEDE ABRIR LA VISTA 3D. CONSULTA LA PELÍCULA.';return null;}
 renderer.setPixelRatio(Math.min(window.devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;renderer.outputColorSpace=THREE.SRGBColorSpace;container.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label','Humanoide animado sobre la cancha 3D. Arrastra para girar.');renderer.domElement.setAttribute('role','img');
 const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.07;controls.minDistance=1.6;controls.maxDistance=65;controls.maxPolarAngle=Math.PI*.48;controls.target.set(0,.9,0);controls.enablePan=true;
 scene.add(new THREE.HemisphereLight(0xffffff,0xc9c9bd,2.2));const key=new THREE.DirectionalLight(0xffffff,3);key.position.set(3,6,5);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-6;key.shadow.camera.right=6;key.shadow.camera.top=6;key.shadow.camera.bottom=-6;key.shadow.camera.near=.1;key.shadow.camera.far=25;key.shadow.bias=-.0004;key.shadow.normalBias=.01;scene.add(key);scene.add(key.target);const rim=new THREE.DirectionalLight(0xffffff,1.1);rim.position.set(-4,4,-3);scene.add(rim);
 const ground=new THREE.Mesh(new THREE.PlaneGeometry(160,160),new THREE.MeshStandardMaterial({color:'#f7f7f3',roughness:.92}));ground.rotation.x=-Math.PI/2;ground.position.y=-.012;ground.receiveShadow=true;scene.add(ground);
 const loader=new GLTFLoader();const asset=state.data.metadata.humanoid||'/assets/humanoid.glb';let gltf;try{gltf=await loader.loadAsync(asset);}catch(error){container.querySelector('#viewer-status').textContent='EL CUERPO 3D NO PUDO CARGAR. LA PELÍCULA SIGUE DISPONIBLE.';renderer.dispose();return null;}
 const body=gltf.scene;scene.add(body);body.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;o.frustumCulled=false;}});const skel=new THREE.SkeletonHelper(body);skel.visible=false;skel.material.depthTest=false;skel.material.transparent=true;skel.material.opacity=.75;skel.material.color?.set('#151515');skel.renderOrder=4;scene.add(skel);
 let mixer=null,actions=[],animationDuration=durationFrom(gltf);const animationStart=state.data.metadata.animationStart||0,animationEnd=state.data.metadata.animationEnd??(animationStart+animationDuration);if(gltf.animations.length){mixer=new THREE.AnimationMixer(body);actions=gltf.animations.map(clip=>{const a=mixer.clipAction(clip);a.setLoop(THREE.LoopOnce,1);a.clampWhenFinished=true;a.play();return a;});}
 const bones={};body.traverse(o=>{if(o.isBone)bones[o.name]=o;});const boneMap=state.data.metadata.rigBoneMap||{};const names=Object.values(boneMap),majorBones=new Set(names),vectorBones=Object.values(bones);
 const arrows=vectorBones.map(()=>{const a=new THREE.ArrowHelper(new THREE.Vector3(0,1,0),new THREE.Vector3(),.2,0xcb241b,.065,.03);a.line.material.depthTest=false;a.cone.material.depthTest=false;a.renderOrder=5;scene.add(a);return a;});let showVectors=true,showFullRig=false,ankleElevation=null,time=state.time,visible=true,view='orbit',lastTarget=new THREE.Vector3(0,.85,0),cameraUser=false;
 const roots=Object.values(bones);const followBone=bones[boneMap.pelvis]||bones.MHR_000||roots.at(-1);const target=new THREE.Vector3();
 const box=new THREE.Box3().setFromObject(body);const size=box.getSize(new THREE.Vector3());const baseCenter=box.getCenter(new THREE.Vector3());if(!followBone)controls.target.copy(baseCenter);const bodyHeight=Math.max(1,size.y);
 controls.target.set(baseCenter.x,Math.max(.8,baseCenter.y),baseCenter.z);camera.position.copy(controls.target).add(new THREE.Vector3(2.6,1.1,3.8));lastTarget.copy(controls.target);controls.update();
 if(state.data.metadata.pitch!==false){loader.load(state.data.metadata.pitch||'/assets/pitch.glb',p=>{p.scene.position.set(-36,0,0);p.scene.traverse(o=>{if(o.isMesh)o.receiveShadow=true;});scene.add(p.scene);},undefined,()=>{});}
 const ballGroup=new THREE.Group(),ballBody=new THREE.Mesh(new THREE.SphereGeometry(.11,32,20),new THREE.MeshStandardMaterial({color:'#d2e64c',roughness:.3}));ballBody.castShadow=true;ballGroup.add(ballBody);for(let i=0;i<3;i++){const seam=new THREE.Mesh(new THREE.TorusGeometry(.111,.0014,5,64),new THREE.MeshStandardMaterial({color:'#30331f',roughness:.7}));if(i===1)seam.rotation.x=Math.PI/2;if(i===2)seam.rotation.y=Math.PI/2;ballGroup.add(seam);}ballGroup.visible=false;scene.add(ballGroup);const ballPositions=new Map((state.data.ball3d?.samples||[]).map(b=>[b.sourceFrame,b.position]));
 const trailMaterial=new THREE.LineBasicMaterial({color:'#cb241b',transparent:true,opacity:.5,depthTest:false});const trail=new THREE.Line(new THREE.BufferGeometry(),trailMaterial);trail.renderOrder=3;scene.add(trail);const footBone=bones[boneMap.leftAnkle]||bones[boneMap.left_ankle];
 function poseAt(t){if(!mixer)return;for(const a of actions){a.enabled=true;a.paused=false;}mixer.setTime(Math.max(0,Math.min(animationDuration-.00001,t-animationStart)));body.updateMatrixWorld(true);}
 function setTime(t){time=t;poseAt(t);const observation=state.sample;body.visible=observation?.valid!==false&&t>=animationStart-.02&&t<=animationEnd+.02;container.dataset.observed=body.visible?'true':'false';const ballPosition=ballPositions.get(state.frame+2422);ballGroup.visible=false;if(ballPosition)ballGroup.position.fromArray(ballPosition);skel.visible=body.visible&&document.getElementById('bones').checked;trail.visible=body.visible&&showVectors;if(footBone&&mixer&&trail.visible){const points=[];for(let st=Math.max(animationStart,t-1);st<=t+.0001;st+=.1){poseAt(st);points.push(footBone.getWorldPosition(new THREE.Vector3()));}poseAt(t);trail.geometry.dispose();trail.geometry=new THREE.BufferGeometry().setFromPoints(points);}ankleElevation=null;if(mixer){const start=vectorBones.map(b=>b.getWorldPosition(new THREE.Vector3()));const delta=.1001,fullWindow=t+delta<=animationEnd+.000001;poseAt(Math.min(t+delta,animationEnd-.00001));const end=vectorBones.map(b=>b.getWorldPosition(new THREE.Vector3()));poseAt(t);const fi=vectorBones.indexOf(footBone);if(fi>=0){const v=end[fi].clone().sub(start[fi]);if(fullWindow&&v.length()>.00001)ankleElevation=Math.atan2(v.y,Math.hypot(v.x,v.z))*180/Math.PI;}arrows.forEach((a,i)=>{const v=end[i].sub(start[i]),length=v.length();a.visible=body.visible&&fullWindow&&showVectors&&(showFullRig||majorBones.has(vectorBones[i].name))&&length>.0008&&length<.65;if(a.visible){a.position.copy(start[i]);a.setDirection(v.normalize());a.setLength(length*4,Math.min(length*1.2,.07),Math.min(length*.6,.035));}});}else arrows.forEach(a=>a.visible=false);if(followBone){followBone.getWorldPosition(target);target.y=Math.max(.65,target.y);const offset=target.clone().sub(lastTarget);if(offset.length()<3&&!cameraUser){controls.target.add(offset);camera.position.add(offset);}lastTarget.copy(target);}key.position.copy(controls.target).add(new THREE.Vector3(3,6,5));key.target.position.copy(controls.target);}
 function setView(v){view=v;cameraUser=false;const t=controls.target.clone();const views={orbit:[2.6,1.1,3.8],front:[0,.3,4.9],side:[4.9,.35,0],top:[.1,7,.01]};camera.position.copy(t).add(new THREE.Vector3(...(views[v]||views.orbit)));controls.update();}
 controls.addEventListener('start',()=>{cameraUser=true;view='manual';});controls.addEventListener('end',()=>{cameraUser=false;lastTarget.copy(controls.target);});
 const observer=new IntersectionObserver(([e])=>visible=e.isIntersecting,{rootMargin:'150px'});observer.observe(container);const resize=new ResizeObserver(()=>{const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();});resize.observe(container);
 let then=0;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;function render(now){requestAnimationFrame(render);if(!visible||document.hidden)return;const dt=Math.min((now-then)/1000,.05);then=now;if(view==='orbit'&&!reduce&&!cameraUser){const offset=camera.position.clone().sub(controls.target);offset.applyAxisAngle(new THREE.Vector3(0,1,0),dt*.055);camera.position.copy(controls.target).add(offset);}controls.update();renderer.render(scene,camera);}requestAnimationFrame(render);
 container.classList.add('loaded');const info=document.getElementById('rig-info');if(info)info.textContent=`${Object.keys(bones).length} HUESOS · Δ0.100 s DE REPLAY · VECTORES ×4`;
 setTime(time);renderer.domElement.addEventListener('webglcontextlost',()=>{container.classList.remove('loaded');container.querySelector('#viewer-status').textContent='VISTA 3D PAUSADA POR EL DISPOSITIVO. RECARGA O ABRE LA PELÍCULA.';});
 window.addEventListener('pagehide',()=>{observer.disconnect();resize.disconnect();controls.dispose();scene.traverse(o=>{o.geometry?.dispose();if(o.material){(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose());}});renderer.dispose();},{once:true});
 return{setTime,setView,getAnkleElevation(){return body.visible?ankleElevation:null;},setFullRig(v){showFullRig=v;setTime(time);},getKneeAngle(){if(!body.visible)return null;const names=['leftHip','leftKnee','leftAnkle'],points=names.map(n=>bones[boneMap[n]]?.getWorldPosition(new THREE.Vector3()).toArray());return jointAngle(...points);},setVectors(v){showVectors=v;setTime(time);},setBones(v){skel.visible=v&&body.visible;}};
}
function durationFrom(gltf){return gltf.animations.reduce((m,c)=>Math.max(m,c.duration),0)||11.4;}
